                    "_reminderQueue").Clear();
                GetField<HashSet<Guid>>(
                    window,
                    "_queuedReminderIds").Clear();
                GetField<DispatcherTimer>(window, "_scheduledTaskTimer").Stop();

                if (args.Contains("--todo-arrow-only", StringComparer.OrdinalIgnoreCase))
                {
