    private static int RunScheduledPickerPreview(Application application)
    {
        var preview = new TodoWindow
        {
            AllowsTransparency = false,
            Background = Brushes.White,
            Height = 650,
            Left = 420,
            ShowInTaskbar = true,
            Title = "小鲁班日期时间选择器预览",
            Top = 220,
            Topmost = false,
            WindowStyle = WindowStyle.SingleBorderWindow,
            ScheduledTasks = new ObservableCollection<ScheduledTaskItem>
            {
                new()
                {
                    Text = "修改窗口界面回归：确认橘色主题、循环勾选和确定按钮",
                    DueAt = DateTimeOffset.Now.AddDays(1),
                    CreatedAt = DateTimeOffset.Now,
                    RepeatInterval = TimeSpan.FromHours(2)
                }
            }
        };
        if (preview.Content is FrameworkElement previewContent)
        {
            previewContent.Height = 414;
            previewContent.VerticalAlignment = VerticalAlignment.Top;
        }

        Invoke(preview, "SelectTaskPage", true, false);
        preview.AllowApplicationClose();
        application.ShutdownMode = ShutdownMode.OnMainWindowClose;
        application.Run(preview);
        return 0;
    }

