                requestedRepeatRule = repeatRule;
                requestedQuietHours = quietHours;
            };

            var futureLocal = DateTime.Now.AddHours(2);
            futureLocal = new DateTime(
                futureLocal.Year,
                futureLocal.Month,
                futureLocal.Day,
                futureLocal.Hour,
                futureLocal.Minute,
                futureLocal.Second,
                DateTimeKind.Unspecified);
            while (TimeZoneInfo.Local.IsInvalidTime(futureLocal))
