            TimeSpan? requestedEditRepeatInterval = null;
            ScheduledRepeatRule? requestedEditRepeatRule = null;
            ScheduledQuietHours? requestedEditQuietHours = null;
            todoWindow.ScheduledTaskEditRequested += (
