            var scheduledEditorQuietHoursEditor = GetField<Grid>(
                scheduledEditor,
                "QuietHoursEditor");
            var scheduledEditorQuietHoursToggle = GetField<CheckBox>(
                scheduledEditor,
                "QuietHoursToggle");
            var scheduledEditorQuietHoursStart = GetField<TextBox>(
