            var scheduledEditorQuietHoursEnd = GetField<TextBox>(
                scheduledEditor,
                "QuietHoursEndTextBox");
            var scheduledEditorRepeatCount = GetField<TextBox>(
                scheduledEditor,
                "RepeatCountTextBox");
            var scheduledEditorRepeatUnit = GetField<ComboBox>(
                scheduledEditor,
