            var scheduledEditorChrome = GetField<Border>(
                scheduledEditor,
                "EditorChrome");
            Assert(scheduledEditor.IsVisible &&
                   ReferenceEquals(scheduledEditor.Owner, todoWindow) &&
                   ReferenceEquals(scheduledEditor.Item, editItem) &&
