                   scheduledEditor.ResizeMode == ResizeMode.CanResize &&
                   scheduledEditor.FontFamily.Source == "Microsoft YaHei" &&
                   scheduledEditor.Title == "修改定时任务" &&
                   scheduledEditorText.Text == editItem.Text &&
