            Assert(Math.Abs(scrollViewer.VerticalOffset - 12.5) < 0.75,
                $"待办 Pixel 滚动必须保留小数级中间位置，实际 offset={scrollViewer.VerticalOffset:F2}");
            var todoVerticalScrollBar =
