                .Value as SolidColorBrush;
            var todoInputFocusBorder = todoInputFocusTrigger.Setters
                .OfType<Setter>()
                .Single(setter =>
                    setter.TargetName == "TodoInputBorder" &&
                    setter.Property == Border.BorderBrushProperty)
