    private static string ExtractPrivateMethodSource(string source, string methodName)
    {
        var marker = $"{methodName}(";
        var searchFrom = 0;
        var start = -1;
        while (searchFrom < source.Length)
        {
            var candidate = source.IndexOf(marker, searchFrom, StringComparison.Ordinal);
            if (candidate < 0)
            {
                break;
            }

            var precedingIndex = candidate - 1;
            if (precedingIndex >= 0 &&
                (char.IsLetterOrDigit(source[precedingIndex]) ||
                 source[precedingIndex] == '_'))
            {
                searchFrom = candidate + marker.Length;
                continue;
            }

            var lineStart = source.LastIndexOf('\n', candidate);
            lineStart = lineStart < 0 ? 0 : lineStart + 1;
            var lineEnd = source.IndexOf('\n', candidate);
            lineEnd = lineEnd < 0 ? source.Length : lineEnd;
            var declarationLine = source[lineStart..lineEnd];
            if (declarationLine.Contains("private ", StringComparison.Ordinal) ||
                declarationLine.Contains("internal ", StringComparison.Ordinal))
            {
                start = lineStart;
                break;
            }

            searchFrom = candidate + marker.Length;
        }

        if (start < 0)
        {
            throw new InvalidOperationException($"找不到源码方法：{methodName}");
        }

        var end = source.IndexOf("\n    private ", start + 1, StringComparison.Ordinal);
        return end < 0 ? source[start..] : source[start..end];
    }

    private static T? FindVisualDescendant<T>(DependencyObject root)
        where T : DependencyObject
    {
        for (var index = 0; index < VisualTreeHelper.GetChildrenCount(root); index++)
        {
            var child = VisualTreeHelper.GetChild(root, index);
            if (child is T match)
            {
                return match;
            }

            var descendant = FindVisualDescendant<T>(child);
            if (descendant is not null)
            {
                return descendant;
            }
        }

        return null;
    }

    private static IEnumerable<T> FindVisualDescendants<T>(DependencyObject root)
        where T : DependencyObject
    {
        for (var index = 0; index < VisualTreeHelper.GetChildrenCount(root); index++)
        {
            var child = VisualTreeHelper.GetChild(root, index);
            if (child is T match)
            {
                yield return match;
            }

            foreach (var descendant in FindVisualDescendants<T>(child))
            {
                yield return descendant;
            }
        }
    }

    private static void PumpDispatcher(TimeSpan duration)
    {
        var frame = new DispatcherFrame();
        // Background priority can be starved by a continuously subscribed
        // CompositionTarget.Rendering callback, turning a 30 ms pump into
        // several seconds and letting the clip finish before an intermediate
        // state assertion. Normal priority keeps the requested wall-clock bound.
        var timer = new DispatcherTimer(DispatcherPriority.Normal)
        {
            Interval = duration
        };
        timer.Tick += (_, _) =>
        {
            timer.Stop();
            frame.Continue = false;
        };
        timer.Start();
        Dispatcher.PushFrame(frame);
    }

    private static RenderingEventArgs CreateRenderingEventArgs(TimeSpan renderingTime)
    {
        var constructor = typeof(RenderingEventArgs).GetConstructor(
            BindingFlags.Instance | BindingFlags.NonPublic,
            binder: null,
            [typeof(TimeSpan)],
            modifiers: null)
            ?? throw new InvalidOperationException(
                "找不到 RenderingEventArgs(TimeSpan) 内部构造函数");
        return (RenderingEventArgs)constructor.Invoke([renderingTime]);
    }

    private static void AssertTodoArrowPositionMatrixContract(MainWindow window)
    {
        var monitorWorkAreaType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
        var positionCache = GetRawField(window, "_todoWindowPositionCache")!;
        var petViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        var originalBubbleMode = GetRawField(window, "_bubbleMode")!;
        var noneBubbleMode = GetNestedEnum("BubbleMode", "None");
        var todoBubbleMode = GetNestedEnum("BubbleMode", "Todo");
        var cuteBubbleMode = GetNestedEnum("BubbleMode", "Cute");
        var originalWindowVisible = window.IsVisible;
        var originalWindowHitTestVisible = window.IsHitTestVisible;
        var originalTodoHitTestVisible = todoWindow.IsHitTestVisible;
        var originalSuppressDeactivate =
            GetField<bool>(window, "_suppressTodoWindowDeactivate");
        var originalPetSizeScale = GetField<double>(window, "_petSizeScale");
        var originalLeft = window.Left;
        var originalTop = window.Top;
        var observedTailSides = new HashSet<bool>();

        try
        {
            window.IsHitTestVisible = false;
            todoWindow.IsHitTestVisible = false;
            SetField(window, "_suppressTodoWindowDeactivate", true);
            Invoke(window, "ApplyPetSizeScale", 1d, false, false);
            if (!window.IsVisible)
            {
                window.Show();
            }

            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var petHost = GetField<Grid>(window, "PetHost");
            var clickDown = new MouseButtonEventArgs(
                Mouse.PrimaryDevice,
                Environment.TickCount,
                MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonDownEvent,
                Source = petHost
            };
            var clickUp = new MouseButtonEventArgs(
                Mouse.PrimaryDevice,
                Environment.TickCount,
                MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                Source = petHost
            };
            Invoke(
                window,
                "PetHost_MouseLeftButtonDown",
                petHost,
                clickDown);
            Invoke(
                window,
                "PetHost_MouseLeftButtonUp",
                petHost,
                clickUp);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(
                GetRawField(window, "_bubbleMode")?.ToString() == "Cute" &&
                GetField<Popup>(window, "BubblePopup").IsOpen &&
                GetRawField(window, "_activeClip") is not null,
                "真实左键单击小鲁班必须启动卖萌动作并显示可爱对话框");
            AssertCuteBubbleTailAtCurrentPosition(
                window,
                "real left-click reaction");
            var clickReactionClip =
                GetRawField(window, "_activeClip")
                ?? throw new InvalidOperationException(
                    "真实左键单击没有生成可结束的卖萌动作");
            Invoke(window, "CompleteActiveClip", clickReactionClip);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(
                GetRawField(window, "_bubbleMode")?.ToString() == "None" &&
                !GetField<Popup>(window, "BubblePopup").IsOpen,
                "卖萌动作结束后可爱对话框必须正常收起，不能残留旧箭头方向");

            Invoke(window, "SetBubbleMode", todoBubbleMode);
            PumpDispatcher(TimeSpan.FromMilliseconds(40));
            Assert(todoWindow.IsVisible,
                "箭头位置矩阵必须使用真实可见的 Owned TodoWindow");

            var workArea = (Rect)InvokeStatic(
                monitorWorkAreaType,
                "GetForWindow",
                window)!;
            var windowWidth = window.ActualWidth > 0
                ? window.ActualWidth
                : window.Width;
            var windowHeight = window.ActualHeight > 0
                ? window.ActualHeight
                : window.Height;
            var horizontalInset = Math.Min(
                24,
                Math.Max(0, (workArea.Width - windowWidth) / 4));
            var verticalInset = Math.Min(
                24,
                Math.Max(0, (workArea.Height - windowHeight) / 4));
            var xPositions = new[]
            {
                (
                    Name: "left",
                    Value: workArea.Left + horizontalInset),
                (
                    Name: "center",
                    Value: workArea.Left + (workArea.Width - windowWidth) / 2),
                (
                    Name: "right",
                    Value: workArea.Right - windowWidth - horizontalInset)
            };
            var yPositions = new[]
            {
                (
                    Name: "top",
                    Value: workArea.Top + verticalInset),
                (
                    Name: "middle",
                    Value: workArea.Top + (workArea.Height - windowHeight) / 2),
                (
                    Name: "bottom",
                    Value: workArea.Bottom - windowHeight - verticalInset)
            };

            foreach (var xPosition in xPositions)
            {
                foreach (var yPosition in yPositions)
                {
                    PositionTodoArrowMatrixCase(
                        window,
                        todoWindow,
                        petViewbox,
                        positionCache,
                        xPosition.Value,
                        yPosition.Value);
                    var result = AssertTodoArrowAtCurrentPosition(
                        todoWindow,
                        petViewbox,
                        $"{xPosition.Name}/{yPosition.Name}");
                    observedTailSides.Add(result.TailOnRight);
                    Assert(!result.TopClamped && !result.BottomClamped,
                        $"{xPosition.Name}/{yPosition.Name}完全位于工作区时，" +
                        "箭头必须直接指向人物物理中心而不是提前夹紧");
                }
            }

            var centerX =
                workArea.Left + (workArea.Width - windowWidth) / 2;
            PositionTodoArrowMatrixCase(
                window,
                todoWindow,
                petViewbox,
                positionCache,
                centerX,
                workArea.Top - windowHeight);
            var topClamp = AssertTodoArrowAtCurrentPosition(
                todoWindow,
                petViewbox,
                "above-work-area clamp");
            observedTailSides.Add(topClamp.TailOnRight);
            Assert(topClamp.TopClamped && !topClamp.BottomClamped,
                "人物中心越过工作区上方时，真实箭头必须夹紧到气泡上安全边界");

            PositionTodoArrowMatrixCase(
                window,
                todoWindow,
                petViewbox,
                positionCache,
                centerX,
                workArea.Bottom + windowHeight * 0.1);
            var bottomClamp = AssertTodoArrowAtCurrentPosition(
                todoWindow,
                petViewbox,
                "below-work-area clamp");
            observedTailSides.Add(bottomClamp.TailOnRight);
            Assert(!bottomClamp.TopClamped && bottomClamp.BottomClamped,
                "人物中心越过工作区下方时，真实箭头必须夹紧到气泡下安全边界");

            Assert(observedTailSides.SetEquals([false, true]),
                "3x3真实位置矩阵必须实际覆盖待办位于人物左右两侧，" +
                "不能只直接调用SetTailPlacement假覆盖翻转");

            Invoke(window, "SetBubbleMode", noneBubbleMode);
            window.Left = workArea.Left + horizontalInset;
            window.Top =
                workArea.Top + (workArea.Height - windowHeight) / 2;
            window.UpdateLayout();
            SetField(window, "_cuteBubblePlacedOnLeft", null);
            Invoke(window, "SetBubbleMode", cuteBubbleMode);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var cutePopup = GetField<Popup>(window, "BubblePopup");
            Assert(cutePopup.IsOpen &&
                   cutePopup.Placement == PlacementMode.Right,
                "人物位于屏幕左侧时，可爱对话框应优先请求放到右边");
            Assert(!AssertCuteBubbleTailAtCurrentPosition(
                       window,
                       "left-side pet"),
                "人物位于屏幕左侧时，气泡实际应位于人物右边且箭头向左指向人物");

            window.Left =
                workArea.Right - windowWidth - horizontalInset;
            window.UpdateLayout();
            SetField(window, "_cuteBubblePlacedOnLeft", null);
            Invoke(window, "UpdateCuteBubblePlacementAndTail");
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            Assert(cutePopup.Placement == PlacementMode.Left,
                "人物位于屏幕右侧时，可爱对话框应优先请求放到左边");
            Assert(AssertCuteBubbleTailAtCurrentPosition(
                       window,
                       "right-side pet"),
                "人物位于屏幕右侧时，气泡实际应位于人物左边且箭头向右指向人物");

            Assert(!(bool)InvokeStatic(
                       typeof(MainWindow),
                       "ResolveCuteBubbleIsOnLeft",
                       -1580d,
                       -1353d,
                       -1800d,
                       -1610d,
                       true)!,
                "负坐标副屏上气泡实际位于人物右侧时，箭头必须仍向左指向人物");
            Assert((bool)InvokeStatic(
                       typeof(MainWindow),
                       "ResolveCuteBubbleIsOnLeft",
                       1450d,
                       1677d,
                       1700d,
                       1890d,
                       false)!,
                "多屏物理坐标中气泡实际位于人物左侧时，箭头必须向右指向人物");
            Assert((bool)InvokeStatic(
                       typeof(MainWindow),
                       "ResolveCuteBubbleIsOnLeft",
                       double.NaN,
                       0d,
                       0d,
                       190d,
                       true)!,
                "Popup HWND 正在跨屏重建而坐标暂不可用时，必须保留请求侧作为安全回退");
        }
        finally
        {
            Invoke(window, "SetBubbleMode", noneBubbleMode);
            Invoke(
                window,
                "ApplyPetSizeScale",
                originalPetSizeScale,
                false,
                false);
            window.Left = originalLeft;
            window.Top = originalTop;
            window.IsHitTestVisible = originalWindowHitTestVisible;
            todoWindow.IsHitTestVisible = originalTodoHitTestVisible;
            SetField(
                window,
                "_suppressTodoWindowDeactivate",
                originalSuppressDeactivate);
            if (!Equals(originalBubbleMode, noneBubbleMode))
            {
                Invoke(window, "SetBubbleMode", originalBubbleMode);
            }

            if (!originalWindowVisible)
            {
                window.Hide();
            }

            PumpDispatcher(TimeSpan.FromMilliseconds(20));
        }
    }

    private static bool AssertCuteBubbleTailAtCurrentPosition(
        MainWindow window,
        string stage)
    {
        Invoke(window, "ReconcileCuteBubbleTailWithActualPlacement");
        PumpDispatcher(TimeSpan.FromMilliseconds(10));

        var popup = GetField<Popup>(window, "BubblePopup");
        var popupChild = popup.Child as FrameworkElement
            ?? throw new InvalidOperationException(
                $"{stage}: 可爱对话框缺少可测量的 Popup 子元素");
        var petViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        var bubbleHost = GetField<Grid>(window, "BubbleHost");
        var tailHost = GetField<Grid>(window, "BubbleTailHost");
        var tailPolygon =
            GetField<System.Windows.Shapes.Polygon>(
                window,
                "BubbleTailPolygon");
        var firstColumn =
            GetField<ColumnDefinition>(window, "BubbleBodyColumn");
        var secondColumn =
            GetField<ColumnDefinition>(window, "BubbleTailColumn");

        popupChild.UpdateLayout();
        var popupTopLeft = popupChild.PointToScreen(new Point(0, 0));
        var popupBottomRight = popupChild.PointToScreen(
            new Point(popupChild.ActualWidth, popupChild.ActualHeight));
        var petTopLeft = petViewbox.PointToScreen(new Point(0, 0));
        var petBottomRight = petViewbox.PointToScreen(
            new Point(petViewbox.ActualWidth, petViewbox.ActualHeight));
        var popupCenterX =
            (popupTopLeft.X + popupBottomRight.X) / 2;
        var petCenterX =
            (petTopLeft.X + petBottomRight.X) / 2;
        var popupIsOnLeft = popupCenterX < petCenterX;

        Assert(
            GetField<bool?>(window, "_cuteBubbleTailPlacedOnLeft") ==
            popupIsOnLeft,
            $"{stage}: 箭头侧必须按 Popup 最终物理位置复核，不能只看请求的 Placement");
        Assert(
            popupIsOnLeft
                ? firstColumn.Width.IsAuto &&
                  Math.Abs(secondColumn.Width.Value - 12) <= 0.01 &&
                  Grid.GetColumn(bubbleHost) == 0 &&
                  Grid.GetColumn(tailHost) == 1
                : Math.Abs(firstColumn.Width.Value - 12) <= 0.01 &&
                  secondColumn.Width.IsAuto &&
                  Grid.GetColumn(tailHost) == 0 &&
                  Grid.GetColumn(bubbleHost) == 1,
            $"{stage}: 气泡翻边时 215 DIP 正文列和 12 DIP 箭头列必须一起交换");
        Assert(tailPolygon.Points.Count == 3,
            $"{stage}: 可爱气泡箭头必须保持三角形几何");

        var tip = tailPolygon.PointToScreen(tailPolygon.Points[1]);
        var baseCenter = tailPolygon.PointToScreen(new Point(
            (tailPolygon.Points[0].X + tailPolygon.Points[2].X) / 2,
            (tailPolygon.Points[0].Y + tailPolygon.Points[2].Y) / 2));
        Assert(
            popupIsOnLeft ? tip.X > baseCenter.X : tip.X < baseCenter.X,
            $"{stage}: 箭头尖端必须朝向小鲁班所在的一侧");
        Assert(
            Math.Abs(tip.X - petCenterX) <
            Math.Abs(baseCenter.X - petCenterX),
            $"{stage}: 箭头尖端在物理屏幕坐标中必须比底边更接近小鲁班");

        return popupIsOnLeft;
    }

    private static void PositionTodoArrowMatrixCase(
        MainWindow window,
        TodoWindow todoWindow,
        Viewbox petViewbox,
        object positionCache,
        double left,
        double top)
    {
        window.Left = left;
        window.Top = top;
        window.UpdateLayout();
        PumpDispatcher(TimeSpan.FromMilliseconds(20));
        Invoke(positionCache, "InvalidateGeometry");
        Invoke(window, "UpdateTodoWindowPosition");
        todoWindow.UpdateLayout();
        PumpDispatcher(TimeSpan.FromMilliseconds(20));

        // A native SetWindowPos can synchronously update the child HWND before
        // WPF publishes its transform. Re-run the production placement once
        // after layout so this assertion observes the same settled coordinates
        // a user sees, rather than a transient test-harness transform.
        Invoke(positionCache, "InvalidateGeometry");
        Invoke(window, "UpdateTodoWindowPosition");
        window.UpdateLayout();
        todoWindow.UpdateLayout();
        PumpDispatcher(TimeSpan.FromMilliseconds(10));
        Assert(petViewbox.IsVisible && todoWindow.IsVisible,
            "箭头位置矩阵每个样本都必须保持人物和待办窗口真实可见");
    }

    private static (
        bool TailOnRight,
        bool TopClamped,
        bool BottomClamped) AssertTodoArrowAtCurrentPosition(
            TodoWindow todoWindow,
            Viewbox petViewbox,
            string stage)
    {
        var petBounds = GetVisualPhysicalBounds(petViewbox);
        var petCenterX = petBounds.Left + petBounds.Width / 2;
        var petCenterY = petBounds.Top + petBounds.Height / 2;
        var todoOrigin = todoWindow.PointToScreen(new Point(0, 0));
        var todoBottomRight = todoWindow.PointToScreen(
            new Point(todoWindow.ActualWidth, todoWindow.ActualHeight));
        var dpi = VisualTreeHelper.GetDpi(todoWindow);
        var dpiScaleY = Math.Max(0.01, dpi.DpiScaleY);
        var todoCenterX = (todoOrigin.X + todoBottomRight.X) / 2;
        var expectedTailOnRight = todoCenterX <= petCenterX;
        var actualTailOnRight = GetField<bool>(todoWindow, "_tailOnRight");
        Assert(actualTailOnRight == expectedTailOnRight,
            $"{stage}箭头左右方向必须按最终实际Todo HWND中心相对人物中心决定");

        var tailHost = GetField<Grid>(todoWindow, "TailHost");
        var tailPolygon = GetField<System.Windows.Shapes.Polygon>(
            todoWindow,
            "TailPolygon");
        Assert(tailPolygon.Points.Count == 3,
            $"{stage}箭头必须保持三角形尖端几何");
        var localTip = tailPolygon.Points[1];
        var minimumPointX = tailPolygon.Points.Min(point => point.X);
        var maximumPointX = tailPolygon.Points.Max(point => point.X);
        AssertClose(
            localTip.X,
            actualTailOnRight ? maximumPointX : minimumPointX,
            $"{stage}箭头尖端水平朝向");
        var physicalTip = tailPolygon.PointToScreen(localTip);
        var expectedContactX = actualTailOnRight
            ? petBounds.Left
            : petBounds.Right;
        Assert(Math.Abs(physicalTip.X - expectedContactX) <= 2.01,
            $"{stage}箭头尖端必须接触人物当前物理边界：" +
            $"tip={physicalTip.X:F3}px, pet={expectedContactX:F3}px");

        var minimumTailTop = 18d;
        var maximumTailTop = Math.Max(
            minimumTailTop,
            todoWindow.ActualHeight - 36);
        var requestedTailCenterDip =
            (petCenterY - todoOrigin.Y) / dpiScaleY;
        var expectedTailTop = Math.Clamp(
            requestedTailCenterDip - 9,
            minimumTailTop,
            maximumTailTop);
        Assert(
            Math.Abs(tailHost.Margin.Top - expectedTailTop) * dpiScaleY <= 1.01,
            $"{stage}箭头Y必须由真实人物物理中心换算并夹紧：" +
            $"expected={expectedTailTop:F3} DIP, actual={tailHost.Margin.Top:F3} DIP");
        var expectedTipY =
            todoOrigin.Y + (expectedTailTop + 9) * dpiScaleY;
        Assert(Math.Abs(physicalTip.Y - expectedTipY) <= 1.01,
            $"{stage}箭头尖端物理Y必须与动态TailHost中心一致：" +
            $"expected={expectedTipY:F3}px, actual={physicalTip.Y:F3}px");

        var topClamped = Math.Abs(expectedTailTop - minimumTailTop) < 0.01;
        var bottomClamped =
            Math.Abs(expectedTailTop - maximumTailTop) < 0.01;
        if (!topClamped && !bottomClamped)
        {
            Assert(Math.Abs(physicalTip.Y - petCenterY) <= 1.01,
                $"{stage}未夹紧时箭头尖端必须直接指向人物物理中心：" +
                $"tip={physicalTip.Y:F3}px, pet={petCenterY:F3}px");
        }

        return (actualTailOnRight, topClamped, bottomClamped);
    }

    private static object GetNestedEnum(string enumName, string valueName)
    {
        var type = typeof(MainWindow).GetNestedType(enumName, BindingFlags.NonPublic)
            ?? throw new InvalidOperationException($"找不到 MainWindow.{enumName}");
        return Enum.Parse(type, valueName);
    }

    private static object FindSpriteFrameBySuffix(
        MainWindow window,
        string frameNameSuffix)
    {
        var pages = GetDictionaryEntries(GetField<IDictionary>(window, "_spritePages"));
        foreach (var page in pages)
        {
            var frames = GetDictionaryEntries(
                GetProperty<IDictionary>(page.Value!, "Frames"));
            foreach (var frame in frames)
            {
                if (GetSpriteFrameInfo(frame.Value!).Name.EndsWith(
                        frameNameSuffix,
                        StringComparison.Ordinal))
                {
                    return frame.Value!;
                }
            }
        }

        throw new InvalidOperationException($"找不到精灵帧后缀：{frameNameSuffix}");
    }

    private static object CloneSpriteFrameWithName(object frame, string name)
    {
        var info = GetSpriteFrameInfo(frame);
        return Activator.CreateInstance(
                   frame.GetType(),
                   InstanceFlags,
                   binder: null,
                   args:
                   [
                       info.X,
                       info.Y,
                       info.Width,
                       info.Height,
                       info.DestinationX,
                       info.DestinationY,
                       info.PageName,
                       name
                   ],
                   culture: null)
               ?? throw new InvalidOperationException("无法克隆测试SpriteFrame");
    }

    private static void PrimeSpritePageForFrame(MainWindow window, object frame)
    {
        WaitForSpritePagePrefetchToSettle(window);
        var pageName = GetSpriteFrameInfo(frame).PageName;
        if (string.Equals(
                GetRawField(window, "_loadedSpritePageName") as string,
                pageName,
                StringComparison.Ordinal))
        {
            return;
        }

        // This synchronous wrapper is test-only. Production page changes must
        // continue to use the background decoder and old-frame retention.
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        SetField(window, "_failedSpritePageName", null);

        var pageEntry = GetDictionaryEntries(
                GetField<IDictionary>(window, "_spritePages"))
            .Single(entry => string.Equals(
                entry.Key as string,
                pageName,
                StringComparison.Ordinal));
        Invoke(
            window,
            "LoadSpritePageIntoBuffer",
            pageName,
            pageEntry.Value!);
    }

    private static void WaitForPrefetchedSpritePage(
        MainWindow window,
        object expectedFrame)
    {
        var expectedPageName = GetSpriteFrameInfo(expectedFrame).PageName;
        WaitForSpritePagePrefetchToSettle(window);
        Assert(string.Equals(
                   GetRawField(window, "_loadedSpritePageName") as string,
                   expectedPageName,
                   StringComparison.Ordinal) ||
               GetField<IDictionary>(window, "_residentSpritePages")
                   .Contains(expectedPageName),
            $"预测预取必须准备目标分页：{expectedPageName}");
    }

    private static void EvictResidentSpritePageForTest(
        MainWindow window,
        string pageName)
    {
        _ = Invoke(window, "RemoveResidentSpritePage", pageName);
        AssertResidentSpriteCacheAccounting(window, $"测试驱逐 {pageName}");
    }

    private static void WaitForSpritePagePrefetchToSettle(MainWindow window)
    {
        var stopwatch = Stopwatch.StartNew();
        while (GetRawField(window, "_spritePagePrefetchTask") is Task task)
        {
            if (stopwatch.Elapsed >= TimeSpan.FromSeconds(3))
            {
                throw new InvalidOperationException(
                    "精灵分页后台预取必须在3秒内完成并发布到UI线程");
            }

            if (task.IsCompleted)
            {
                PumpDispatcher(TimeSpan.FromMilliseconds(10));
            }
            else
            {
                Thread.Yield();
            }
        }
    }

    private static void WaitForSpritePagePrefetchToSettleWithoutRendering(
        MainWindow window)
    {
        var stopwatch = Stopwatch.StartNew();
        while (GetRawField(window, "_spritePagePrefetchTask") is not null)
        {
            if (stopwatch.Elapsed >= TimeSpan.FromSeconds(3))
            {
                throw new InvalidOperationException(
                    "精灵分页后台预取必须在3秒内由唯一Normal dispatcher回调发布");
            }

            // The production continuation is queued at Normal. A same-priority
            // sentinel drains it but exits before the lower Render priority can
            // present the pending frame, preserving the test's synthetic clock.
            var frame = new DispatcherFrame();
            Dispatcher.CurrentDispatcher.BeginInvoke(
                DispatcherPriority.Normal,
                new Action(() => frame.Continue = false));
            Dispatcher.PushFrame(frame);
            Thread.Yield();
        }
    }

    private static object? Invoke(object instance, string name, params object?[] arguments)
    {
        var method = instance.GetType().GetMethod(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到方法 {instance.GetType().Name}.{name}");
        return method.Invoke(instance, arguments);
    }

    private static object? InvokeOverload(
        object instance,
        string name,
        params object?[] arguments)
    {
        var method = instance.GetType()
            .GetMethods(InstanceFlags)
            .Single(candidate =>
            {
                if (!string.Equals(candidate.Name, name, StringComparison.Ordinal))
                {
                    return false;
                }

                var parameters = candidate.GetParameters();
                return parameters.Length == arguments.Length &&
                       parameters.Select((parameter, index) => (parameter, index))
                           .All(entry =>
                               arguments[entry.index] is null
                                   ? !entry.parameter.ParameterType.IsValueType ||
                                     Nullable.GetUnderlyingType(
                                         entry.parameter.ParameterType) is not null
                                   : entry.parameter.ParameterType.IsInstanceOfType(
                                       arguments[entry.index]));
            });
        return method.Invoke(instance, arguments);
    }

    private static object? InvokeStatic(Type type, string name, params object?[] arguments)
    {
        var method = type.GetMethod(name, StaticFlags)
            ?? throw new InvalidOperationException($"找不到静态方法 {type.Name}.{name}");
        return method.Invoke(null, arguments);
    }

    private static T GetField<T>(object instance, string name)
    {
        var field = instance.GetType().GetField(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到字段 {instance.GetType().Name}.{name}");
        var value = field.GetValue(instance);
        return value is T typed
            ? typed
            : throw new InvalidOperationException(
                $"字段 {instance.GetType().Name}.{name} 类型不正确或为空");
    }

    private static object? GetRawField(object instance, string name)
    {
        var field = instance.GetType().GetField(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到字段 {instance.GetType().Name}.{name}");
        return field.GetValue(instance);
    }

    private static void SetField(object instance, string name, object? value)
    {
        var field = instance.GetType().GetField(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到字段 {instance.GetType().Name}.{name}");
        field.SetValue(instance, value);
    }

    private static T GetProperty<T>(object instance, string name)
    {
        var property = instance.GetType().GetProperty(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到属性 {instance.GetType().Name}.{name}");
        var value = property.GetValue(instance);
        return value is T typed
            ? typed
            : throw new InvalidOperationException(
                $"属性 {instance.GetType().Name}.{name} 类型不正确或为空");
    }

    private static void AssertValidRect(Rect rect, string stage)
    {
        Assert(!rect.IsEmpty &&
               double.IsFinite(rect.Left) &&
               double.IsFinite(rect.Top) &&
               double.IsFinite(rect.Width) &&
               double.IsFinite(rect.Height) &&
               rect.Width > 0 && rect.Height > 0,
            $"{stage}必须是有限且宽高为正的矩形，实际 {rect}");
    }

    private static void AssertClose(double actual, double expected, string message)
    {
        Assert(Math.Abs(actual - expected) < 0.01,
            $"{message}：期望 {expected}，实际 {actual}");
    }

    private static void AssertTaskListScrollBarVisual(
        ScrollBar scrollBar,
        string stage,
        Color expectedColor)
    {
        scrollBar.ApplyTemplate();
        var track = scrollBar.Template.FindName(
                "PART_Track",
                scrollBar) as Track
            ?? throw new InvalidOperationException(
                $"{stage}滚动条缺少PART_Track");
        var thumb = track.Thumb
            ?? throw new InvalidOperationException(
                $"{stage}滚动条缺少Thumb");
        thumb.ApplyTemplate();
        var pill = thumb.Template.FindName(
                "ThumbPill",
                thumb) as Border
            ?? throw new InvalidOperationException(
                $"{stage}滚动块缺少ThumbPill");
        var highlight = thumb.Template.FindName(
                "ThumbHighlight",
                thumb) as Border;
        Assert(Math.Abs(scrollBar.Width - 12) < 0.01 &&
               Math.Abs(pill.Width - 7) < 0.01 &&
               Math.Abs(pill.CornerRadius.TopLeft - 3.5) < 0.01 &&
               pill.Background is SolidColorBrush background &&
               background.Color == expectedColor &&
               highlight is not null,
            $"{stage}滚动块必须是12 DIP热区内的主题色圆角高光药丸，不能使用生硬的系统默认滑块");
    }

    private static void AssertTaskFullTextTheme(
        TodoWindow todoWindow,
        bool scheduled)
    {
        var stage = scheduled ? "定时任务全文窗" : "待办全文窗";
        var chrome = GetField<Border>(
            todoWindow,
            "TaskFullTextPopupChrome");
        var title = GetField<TextBlock>(
            todoWindow,
            "TaskFullTextTitle");
        var preview = GetField<TextBox>(
            todoWindow,
            "TaskFullTextPreviewTextBox");
        var count = GetField<TextBlock>(
            todoWindow,
            "TaskFullTextCountText");
        var expectedChromeBackground = scheduled
            ? Color.FromRgb(0xFF, 0xF8, 0xF1)
            : Color.FromRgb(0xF3, 0xF7, 0xFD);
        var expectedChromeBorder = scheduled
            ? Color.FromRgb(0xEF, 0x94, 0x65)
            : Color.FromRgb(0x8C, 0xB4, 0xF4);
        var expectedShadow = scheduled
            ? Color.FromRgb(0xA8, 0x55, 0x36)
            : Color.FromRgb(0x5B, 0x78, 0xA8);
        var expectedTitle = scheduled
            ? Color.FromRgb(0xC4, 0x5F, 0x3D)
            : Color.FromRgb(0x3E, 0x70, 0xC6);
        var expectedTextBackground = scheduled
            ? Color.FromRgb(0xFF, 0xFC, 0xF8)
            : Color.FromRgb(0xF8, 0xFB, 0xFF);
        var expectedTextBorder = scheduled
            ? Color.FromRgb(0xF1, 0xC1, 0x9E)
            : Color.FromRgb(0xBD, 0xD2, 0xEF);
        var expectedTextForeground = scheduled
            ? Color.FromRgb(0x4B, 0x34, 0x2B)
            : Color.FromRgb(0x30, 0x37, 0x44);
        var expectedSelection = scheduled
            ? Color.FromRgb(0xF5, 0xB0, 0x7D)
            : Color.FromRgb(0xA9, 0xC9, 0xF4);
        var expectedCount = scheduled
            ? Color.FromRgb(0xC1, 0x8A, 0x6C)
            : Color.FromRgb(0x82, 0x95, 0xB3);
        var expectedScrollTrack = scheduled
            ? Color.FromArgb(0x22, 0xD6, 0xA0, 0x6A)
            : Color.FromArgb(0x24, 0x5B, 0x8D, 0xEF);
        var expectedScrollDrag = scheduled
            ? Color.FromRgb(0xD9, 0x7B, 0x2F)
            : Color.FromRgb(0x3E, 0x70, 0xC6);
        var expectedScrollThumb = scheduled
            ? Color.FromRgb(0xE7, 0xA1, 0x5E)
            : Color.FromRgb(0x7B, 0xA6, 0xE8);
        var expectedScrollHover = scheduled
            ? Color.FromRgb(0xF0, 0x9A, 0x48)
            : Color.FromRgb(0x5B, 0x8D, 0xEF);

        preview.ApplyTemplate();
        var scrollBar = FindVisualDescendants<ScrollBar>(preview)
            .FirstOrDefault(candidate =>
                candidate.Orientation == Orientation.Vertical)
            ?? throw new InvalidOperationException(
                $"{stage}缺少自绘纵向滚动条");
        scrollBar.ApplyTemplate();
        Assert(chrome.Background is SolidColorBrush chromeBackground &&
               chromeBackground.Color == expectedChromeBackground &&
               chrome.BorderBrush is SolidColorBrush chromeBorder &&
               chromeBorder.Color == expectedChromeBorder &&
               chrome.Effect is DropShadowEffect shadow &&
               shadow.Color == expectedShadow &&
               title.Foreground is SolidColorBrush titleBrush &&
               titleBrush.Color == expectedTitle &&
               preview.Background is SolidColorBrush textBackground &&
               textBackground.Color == expectedTextBackground &&
               preview.BorderBrush is SolidColorBrush textBorder &&
               textBorder.Color == expectedTextBorder &&
               preview.Foreground is SolidColorBrush textForeground &&
               textForeground.Color == expectedTextForeground &&
               preview.SelectionBrush is SolidColorBrush selection &&
               selection.Color == expectedSelection &&
               count.Foreground is SolidColorBrush countBrush &&
               countBrush.Color == expectedCount &&
               scrollBar.Background is SolidColorBrush scrollTrack &&
               scrollTrack.Color == expectedScrollTrack &&
               scrollBar.BorderBrush is SolidColorBrush scrollDrag &&
               scrollDrag.Color == expectedScrollDrag &&
               scrollBar.Foreground is SolidColorBrush scrollThumb &&
               scrollThumb.Color == expectedScrollThumb &&
               scrollBar.Tag is SolidColorBrush scrollHover &&
               scrollHover.Color == expectedScrollHover &&
               scrollBar.Template.FindName(
                   "PART_Track",
                   scrollBar) is Track,
            $"{stage}必须整套使用{(scheduled ? "橘色" : "蓝色")}主题，" +
            "包括窗口、正文、选区、计数和滚动条");
    }

    private static IDisposable HoldClipboardOpenForTest()
    {
        var ready = new ManualResetEventSlim();
        var release = new ManualResetEventSlim();
        Exception? failure = null;
        var clipboardOpened = false;
        var thread = new Thread(() =>
        {
            try
            {
                var deadline = Stopwatch.StartNew();
                while (!(clipboardOpened = OpenClipboard(IntPtr.Zero)) &&
                       deadline.Elapsed < TimeSpan.FromSeconds(2))
                {
                    Thread.Sleep(10);
                }

                if (!clipboardOpened)
                {
                    failure = new InvalidOperationException(
                        $"测试线程无法独占剪贴板，Win32={Marshal.GetLastWin32Error()}");
                }

                ready.Set();
                if (clipboardOpened)
                {
                    release.Wait(TimeSpan.FromSeconds(10));
                }
            }
            catch (Exception exception)
            {
                failure = exception;
                ready.Set();
            }
            finally
            {
                if (clipboardOpened)
                {
                    _ = CloseClipboard();
                }

                ready.Set();
            }
        })
        {
            IsBackground = true,
            Name = "UiStateChecks clipboard lock"
        };
        thread.Start();
        if (!ready.Wait(TimeSpan.FromSeconds(3)))
        {
            release.Set();
            throw new TimeoutException("测试线程在3秒内未取得剪贴板");
        }

        if (failure is not null)
        {
            release.Set();
            _ = thread.Join(TimeSpan.FromSeconds(1));
            throw new InvalidOperationException(
                "无法建立剪贴板占用回归条件",
                failure);
        }

        return new CallbackDisposable(() =>
        {
            release.Set();
            if (!thread.Join(TimeSpan.FromSeconds(3)))
            {
                throw new TimeoutException("剪贴板占用测试线程未能正常退出");
            }

            ready.Dispose();
            release.Dispose();
        });
    }

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool OpenClipboard(IntPtr newOwner);

    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool CloseClipboard();

    private static double NormalizeCanvasCoordinate(double value) =>
        double.IsNaN(value) ? 0 : value;

    private static void AssertRectClose(Rect actual, Rect expected, string message)
    {
        AssertClose(actual.X, expected.X, $"{message} X");
        AssertClose(actual.Y, expected.Y, $"{message} Y");
        AssertClose(actual.Width, expected.Width, $"{message} Width");
        AssertClose(actual.Height, expected.Height, $"{message} Height");
    }

    private static void Assert(bool condition, string message)
    {
        if (!condition)
        {
            throw new InvalidOperationException(message);
        }
    }

